let category='All',query='',sort='featured',bag=[];
const $=s=>document.querySelector(s);
const money=n=>'₹'+n.toLocaleString('en-IN');
const whatsapp=text=>'https://wa.me/918341676998?text='+encodeURIComponent(text);
const priceHtml=p=>`<span class="price">${money(p.price)}</span>${p.old?`<span class="old-price">${money(p.old)}</span>`:''}`;
function renderProducts() {
  let shown = products.filter(p => (category === 'All' || p.category === category || p.occasion === category) && [p.name, p.category, p.colour, p.fabric].join(' ').toLowerCase().includes(query.toLowerCase()));
  if (sort !== 'featured') shown.sort((a,b) => sort === 'low' ? a.price - b.price : b.price - a.price);
  $('#results-count').textContent = shown.length + (shown.length === 1 ? ' beautiful find' : ' beautiful finds');
  $('#product-grid').innerHTML = shown.map(p => '<article class="product"><div class="product-image" role="button" tabindex="0" data-detail="'+p.id+'" aria-label="View '+p.name+'"><img src="assets/'+p.image+'" alt="'+p.colour+' '+p.category.toLowerCase()+' styling inspiration" loading="lazy"><span class="product-tag">'+p.tag+'</span><span class="product-view">View the details &nbsp; &nearr;</span></div><div class="product-info"><p class="product-type">'+p.category+' &middot; '+p.colour+'</p><button class="product-name" data-detail="'+p.id+'">'+p.name+'</button><div class="product-bottom"><div>'+priceHtml(p)+'</div><div class="swatches" aria-hidden="true">'+p.swatches.map(c=>'<span style="--swatch:'+c+'"></span>').join('')+'</div></div><button class="add-button" data-quick-add="'+p.id+'" aria-label="Add '+p.name+' to bag"><svg><use href="#i-bag"/></svg>'+(p.category==='Dresses'?'Choose your size':'Add to bag')+'</button></div></article>').join('');
  $('#no-results').hidden = shown.length > 0;
}
function setFilter(next){category=next;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===category);b.setAttribute('aria-pressed',b.dataset.filter===category)});renderProducts()}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>setFilter(b.dataset.filter)));
document.querySelectorAll('[data-occasion]').forEach(a=>a.addEventListener('click',()=>{query='';$('#search').value='';setFilter(a.dataset.occasion)}));
$('#sort').addEventListener('change',e=>{sort=e.target.value;renderProducts()});
$('#search-toggle').addEventListener('click',()=>{const panel=$('#search-panel');panel.hidden=!panel.hidden;$('#search-toggle').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){$('#collection').scrollIntoView({behavior:'smooth'});$('#search').focus({preventScroll:true})}});
$('#search').addEventListener('input',e=>{query=e.target.value;renderProducts()});$('#clear-search').addEventListener('click',()=>{query='';$('#search').value='';renderProducts();$('#search').focus()});
$('#menu-toggle').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}));
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function addToBag(id,size){const p=products.find(p=>p.id===id);const selected=size||p.size;const item=bag.find(x=>x.id===id&&x.size===selected);if(item){if(item.quantity>=99){toast('Please contact us for quantities over 99.');return;}item.quantity++;}else bag.push({id,size:selected,quantity:1});updateBag();toast(`${p.name} added to your bag`)}
function showProduct(id){const p=products.find(p=>p.id===id);$('#product-detail').innerHTML=`<div class="detail-layout"><img src="assets/${p.image}" alt="${p.name} in ${p.colour}"><div class="detail-copy"><p class="eyebrow">${p.category.toUpperCase()}</p><h2>${p.name}</h2><p>${priceHtml(p)}</p><p>${p.description}</p><p>Colour: ${p.colour}<br>Fabric: ${p.fabric}</p>${p.category==='Dresses'?'<label for="product-size">Choose your size<select id="product-size"><option>S</option><option>M</option><option>L</option><option>XL</option><option>XXL</option></select></label>':`<p>${p.size}</p>`}<button class="button primary" id="detail-add">Add to bag <span>+</span></button><a class="text-link" target="_blank" rel="noopener" href="${whatsapp(`Hello Vastra by Varahi! I'm interested in ${p.name} (${p.colour}), reference price ${money(p.price)}. Could you share actual photos, availability and the final price?`)}">Ask about this piece <span>↗</span></a><p class="detail-note">Styling image and reference price. Confirm actual photos, fabric, available sizes and final price with us on WhatsApp before ordering.</p></div></div>`;$('#detail-add').onclick=()=>addToBag(p.id,$('#product-size')?.value);openDialog($('#product-dialog'))}
let dialogOpener;function openDialog(dialog){dialogOpener=document.activeElement;dialog.showModal();document.body.style.overflow='hidden'}function closeDialog(dialog){dialog.close();document.body.style.overflow='';dialogOpener?.focus()}
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').onclick=()=>closeDialog(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}});d.addEventListener('close',()=>{document.body.style.overflow=''})});
$('#product-grid').addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');const add=e.target.closest('[data-quick-add]');if(detail)showProduct(Number(detail.dataset.detail));if(add){const p=products.find(p=>p.id===Number(add.dataset.quickAdd));if(p.category==='Dresses')showProduct(p.id);else addToBag(p.id)}});
$('#product-grid').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.product-image')){e.preventDefault();showProduct(Number(e.target.dataset.detail))}});
function updateBag(){const count=bag.reduce((n,i)=>n+i.quantity,0);$('#bag-count').textContent=count;$('#mobile-bag-count').textContent=count;$('#drawer-count').textContent=`(${count})`;$('#bag-toggle').setAttribute('aria-label',`Open shopping bag, ${count} items`);$('#bag-items').innerHTML=bag.length?bag.map((i,index)=>{const p=products.find(p=>p.id===i.id);return `<div class="bag-item"><img src="assets/${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.colour} · ${i.size}</p><span class="price">${money(p.price*i.quantity)}</span><div class="quantity"><button data-qty="${index}" data-delta="-1" aria-label="Decrease quantity of ${p.name}">−</button><span>${i.quantity}</span><button data-qty="${index}" data-delta="1" aria-label="Increase quantity of ${p.name}">+</button></div></div><button class="remove-item" data-remove="${index}" aria-label="Remove ${p.name}">×</button></div>`}).join(''):`<div class="empty-bag"><span>✧</span>Your next favourite belongs here.<p>Explore our collection and add a piece you love.</p><button class="button primary" id="continue-shopping">Explore the collection ↗</button></div>`;$('#bag-summary').innerHTML=bag.length?`<div class="subtotal"><span>Estimated total</span><strong>${money(bag.reduce((n,i)=>n+products.find(p=>p.id===i.id).price*i.quantity,0))}</strong></div><p class="bag-summary-note">We’ll confirm actual photos, availability, delivery charges and the final price with you on WhatsApp. Your message will open for you to review and send.</p><button class="button primary checkout" id="checkout">Order on WhatsApp <span>↗</span></button><p class="bag-session-note">Your bag stays here until you refresh or leave this page.</p>`:'';if($('#checkout'))$('#checkout').onclick=checkout;if($('#continue-shopping'))$('#continue-shopping').onclick=()=>{closeDialog($('#bag-dialog'));$('#collection').scrollIntoView({behavior:'smooth'})}}
$('#bag-items').addEventListener('click',e=>{const q=e.target.closest('[data-qty]'),r=e.target.closest('[data-remove]');if(q){const index=Number(q.dataset.qty);bag[index].quantity=Math.min(99,bag[index].quantity+Number(q.dataset.delta));if(bag[index].quantity<1)bag.splice(index,1);updateBag()}if(r){bag.splice(Number(r.dataset.remove),1);updateBag()}});
function checkout(){if(!bag.length)return;const lines=bag.map(i=>{const p=products.find(p=>p.id===i.id);return `• ${p.name} | ${p.colour} | ${i.size} | Qty: ${i.quantity} | Reference: ${money(p.price*i.quantity)}`});const total=bag.reduce((n,i)=>n+products.find(p=>p.id===i.id).price*i.quantity,0);const message=`Hello Vastra by Varahi! I would like to order these pieces:\n\n${lines.join('\n')}\n\nEstimated total: ${money(total)}\n\nPlease confirm actual photos, fabric, availability, delivery charges and final price. Thank you!`;window.open(whatsapp(message),'_blank','noopener,noreferrer')}
$('#bag-toggle').onclick=()=>{updateBag();openDialog($('#bag-dialog'))};$('#year').textContent=new Date().getFullYear();setFilter('All');updateBag();

$('#mobile-bag-toggle').addEventListener('click',()=>{updateBag();openDialog($('#bag-dialog'))});
$('#reset-filters').addEventListener('click',()=>{query='';$('#search').value='';setFilter('All')});
